<?php
namespace App\Http\Controllers\Sifi;use App\Http\Controllers\Controller;use App\Models\SifiMonitoringObject;use App\Services\Sifi\{DiscoveryCatalog,ResearchSessionWorkspace};use Illuminate\Http\{Request,RedirectResponse};use Illuminate\Support\Facades\Gate;use Illuminate\Validation\Rule;use Inertia\{Inertia,Response};
final class ResearchPlanningController extends Controller {/** @return array<string, list<string>> */
private function forbidden():array{return array_fill_keys(['user_id','provider','url','grant','permit','receipt','rights','evidence','claim','ai','schedule','cost_limit','request_limit','byte_limit'],['prohibited']);}public function index(Request $r,SifiMonitoringObject $object,ResearchSessionWorkspace $w):Response{Gate::authorize('view',$object);return Inertia::render('sifi/research-planning',['object'=>$object->only(['id','name','category','geography','objective','revision','state']),'history'=>$w->history($r->user(),$object),'bounds'=>['query_limit'=>5,'result_limit'=>20,'history_limit'=>30,'retention_days'=>30],'source_types'=>DiscoveryCatalog::TYPES]);}public function store(Request $r,SifiMonitoringObject $object,ResearchSessionWorkspace $w):RedirectResponse{Gate::authorize('update',$object);$v=$r->validate($this->forbidden()+['question'=>['required','string','min:8','max:600'],'object_revision'=>['required','integer','min:1'],'parent_session_id'=>['nullable','uuid'],'query_limit'=>['required','integer','min:1','max:5'],'result_limit'=>['required','integer','min:1','max:20'],'language'=>['nullable',Rule::in(['id','en'])],'source_type'=>['nullable',Rule::in(DiscoveryCatalog::TYPES)],'time_window'=>['nullable','string','max:80']]);$w->create($r->user(),$object,$v);return redirect()->route('sifi.research-planning.index',['object'=>$object->id]);}}
